configMap.content:
logging {
  level  = "info"
  format = "logfmt"
}

discovery.kubernetes "pods" {
  role = "pod"
  selectors {
    role = "pod"
    field = "spec.nodeName=" + sys.env("HOSTNAME")
  }
}

discovery.relabel "pod_labels" {
  targets = discovery.kubernetes.pods.targets
  rule {
    source_labels = ["__meta_kubernetes_namespace"]
    target_label = "namespace"
  }
  rule {
    source_labels = ["__meta_kubernetes_pod_name"]
    target_label = "pod"
  }
  rule {
    source_labels = ["__meta_kubernetes_pod_container_name"]
    target_label = "container"
  }
  rule {
    source_labels = ["__meta_kubernetes_pod_node_name"]
    target_label = "node"
  }
  rule {
    source_labels = ["__meta_kubernetes_pod_label_app"]
    target_label = "app"
  }
  rule {
    source_labels = ["__meta_kubernetes_pod_label_app_kubernetes_io_name"]
    regex = "(.+)"
    target_label = "service_name"
  }
  rule {
    source_labels = ["__meta_kubernetes_pod_label_app"]
    regex = "(.+)"
    target_label = "service_name"
  }
}

loki.source.kubernetes "pods" {
  targets    = discovery.relabel.pod_labels.output
  forward_to = [loki.relabel.cluster.receiver, loki.relabel.apm_apps.receiver]
}

loki.relabel "cluster" {
  forward_to = [loki.write.local.receiver]

  rule {
    action       = "replace"
    target_label = "cluster"
    replacement  = "aws-eks-istio-lab-dev"
  }
}

loki.write "local" {
  endpoint {
    url = "http://loki-gateway.loki.svc.cluster.local/loki/api/v1/push"
  }
}

// Export only application containers to APM; keep the existing Loki stream intact.
loki.relabel "apm_apps" {
  forward_to = [otelcol.receiver.loki.apm.receiver]
  rule {
    source_labels = ["namespace", "container"]
    separator = ";"
    regex = "orders-api;orders-api|orders-worker;orders-worker"
    action = "keep"
  }
}
otelcol.receiver.loki "apm" {
  output { logs = [otelcol.processor.transform.apm.input] }
}
otelcol.processor.transform "apm" {
  error_mode = "ignore"
  log_statements {
    context = "log"
    statements = [
      `set(resource.attributes["service.name"], attributes["service_name"])`,
      `set(resource.attributes["k8s.namespace.name"], attributes["namespace"])`,
      `set(resource.attributes["k8s.pod.name"], attributes["pod"])`,
      `set(resource.attributes["k8s.cluster.name"], "aws-eks-istio-lab-dev")`,
      `merge_maps(cache, ParseJSON(body), "upsert") where IsMatch(body, "^\\{")`,
      `set(severity_text, cache["level"]) where cache["level"] != nil`,
      `set(severity_number, 9) where cache["level"] == "INFO"`,
      `set(severity_number, 17) where cache["level"] == "ERROR" or cache["level"] == "CRITICAL"`,
      `set(trace_id, TraceID(cache["trace_id"])) where cache["trace_id"] != nil`,
      `set(span_id, SpanID(cache["span_id"])) where cache["span_id"] != nil`,
    ]
  }
  output { logs = [otelcol.processor.batch.apm.input] }
}
otelcol.processor.batch "apm" {
  timeout = "5s"
  send_batch_size = 128
  output { logs = [otelcol.exporter.otlp.apm.input] }
}
otelcol.exporter.otlp "apm" {
  client {
    endpoint = "otel-collector-opentelemetry-collector.observability.svc.cluster.local:4317"
    tls { insecure = true }
  }
  sending_queue {
    enabled = true
    queue_size = 128
  }
  retry_on_failure {
    enabled = true
    max_elapsed_time = "300s"
  }
}
